// KI-Zugang aus der Oberfläche (Einstellungen > KI). Aufbau wie ALLY 14 (Stefan 18.10.2026).
// Herkunft prüfen wie bei ALLY 8, Sitzung aus dem Cookie. Der Anthropic-Schlüssel geht nur an den Prüfabruf und an die
// n8n-Zugangsdaten (beide lesen ihn selbst aus dem Formular), nie in die Datenbank und nicht in diese Ausgabe.
// Dieser Ablauf speichert keine Ausführungsdaten.
// Eigene Adresse aus der Anfrage (Host-Kopfzeile, von traefik unverändert weitergegeben), keine festen Werte.
const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(($json.headers || {}).host || '').trim().toLowerCase());
const h = $json.headers || {};
const b = $json.body || {};
const herkunft = String(h.origin || '');
const verweis = String(h.referer || '');
// Verweis muss genau auf die Seite zeigen, danach nur Ende, '/', '?' oder '#' (nicht z. B. /webhook/web-fremd)
const SEITE_PFAD = HOST + '/webhook/web';
const vonSeite = HOST !== '' && verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
const herkunftOk = HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite));
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
// Quelle: 'plattform' (Schlüssel des Anbieters) oder 'kunde'; leer = Standard der Datenbank. Prüfung in ki_web_aktion.
const quelle = String(b.quelle ?? '').trim().toLowerCase().slice(0, 20);
// Nur der Zustand des Schlüssels (leer, Format ungültig, ok), nie der Schlüssel selbst
const s = String(b.schluessel ?? '').trim();
const schluessel = s === '' ? 'leer' : (/^[\x21-\x7e]{10,400}$/.test(s) ? 'ok' : 'format');
return [{ json: { token, herkunft: herkunftOk ? 'ok' : 'ungueltig', schluessel, daten: JSON.stringify({ quelle }) } }];

// Prüfabruf bei Anthropic auswerten (Stefan 18.10.2026): test_ok und eine kurze Meldung, nie der Schlüssel.
// GET /v1/models kostet keine Tokens. 200 = gültig, 401/403 = abgelehnt, sonst nicht erreichbar.
// Fehlertexte von n8n werden nicht übernommen, nur der Fehlercode (z. B. ENOTFOUND).
const K = 'Anthropic prüfen';
const r = $(K).isExecuted ? ($(K).first().json || {}) : {};
const st = Number(r.statusCode) || 0;
let test_ok = false, meldung = '';
if (!st) {
  const e = r.error || {};
  const text = typeof e === 'string' ? e : String(e.message || e.description || '');
  const code = String((typeof e === 'object' && (e.code || (e.cause && e.cause.code))) || (text.match(/\b(E[A-Z_]{2,28}|CERT_[A-Z_]{2,25})\b/) || [])[1] || '');
  meldung = 'Anthropic ist gerade nicht erreichbar' + (/^[A-Z_]{3,30}$/.test(code) ? ' (' + code + ')' : '') + '.';
} else if (st === 200) test_ok = true;
else if (st === 401 || st === 403) meldung = 'Anthropic hat den Schlüssel abgelehnt.';
else meldung = 'Anthropic ist gerade nicht erreichbar (Status ' + st + ').';
return [{ json: { test_ok, meldung } }];

// Feldnamen der n8n-Zugangsart anthropicApi aus GET /api/v1/credentials/schema/anthropicApi bestätigen (Stefan 18.10.2026).
// Ausgabe: weitere Pflichtfelder mit Standardwerten (ohne Schlüssel). apiKey setzt erst "Zugangsdaten setzen" aus dem Formular.
// Unbekannte Pflichtfelder: nichts überschreiben, Meldung zurück.
const STANDARD = { url: 'https://api.anthropic.com', header: false };
const r = $('Schema laden').isExecuted ? ($('Schema laden').first().json || {}) : {};
const st = Number(r.statusCode) || 0;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const props = (body && typeof body === 'object' && body.properties && typeof body.properties === 'object') ? body.properties : null;
const NICHT = 'Der Schlüssel war gültig, konnte aber in n8n nicht gespeichert werden';
let schema_ok = false, meldung = '', felder = {};
if (st !== 200 || !props) meldung = NICHT + ' (' + (st ? 'Status ' + st : 'keine Antwort') + ' beim Lesen der Zugangsart).';
else if (!props.apiKey) meldung = NICHT + ' (Feld apiKey fehlt in der Zugangsart).';
else {
  const pflicht = Array.isArray(body.required) ? body.required.map(String) : [];
  const fehlt = [];
  for (const f of pflicht) {
    if (f === 'apiKey') continue;
    if (Object.prototype.hasOwnProperty.call(STANDARD, f) && props[f]) felder[f] = STANDARD[f];
    else fehlt.push(f);
  }
  if (fehlt.length) { felder = {}; meldung = NICHT + ' (unbekanntes Pflichtfeld ' + fehlt.join(', ').replace(/[^A-Za-z0-9_, ]/g, '').slice(0, 80) + ').'; }
  else schema_ok = true;
}
return [{ json: { schema_ok, felder: JSON.stringify(felder), meldung } }];

// Ergebnis für "Abschließen" zusammenfassen (Stefan 18.10.2026), ohne Schlüssel.
// Leerer oder ungültiger Schlüssel, abgelehnte Prüfung, unpassende Zugangsart oder Fehler beim Speichern in n8n: test_ok false.
const F = $('Formular prüfen').first().json;
const V = $('Vorbereiten').first().json.v || {};
let test_ok = false, meldung = '';
if (F.schluessel === 'leer') meldung = 'Bitte den API-Schlüssel eingeben.';
else if (F.schluessel !== 'ok') meldung = 'Der API-Schlüssel hat kein gültiges Format. Bitte den Schlüssel vollständig aus der Anthropic Console kopieren.';
else if (!$('Prüfung auswerten').isExecuted) meldung = 'Die Prüfung ist fehlgeschlagen.';
else {
  const P = $('Prüfung auswerten').first().json || {};
  test_ok = P.test_ok === true;
  meldung = String(P.meldung || '');
  if (test_ok) {
    const S = $('Schema auswerten').isExecuted ? ($('Schema auswerten').first().json || {}) : {};
    if (S.schema_ok !== true) { test_ok = false; meldung = String(S.meldung || 'Der Schlüssel war gültig, konnte aber in n8n nicht gespeichert werden.'); }
    else if (!$('Zugangsdaten setzen').isExecuted) { test_ok = false; meldung = 'Der Schlüssel war gültig, konnte aber in n8n nicht gespeichert werden.'; }
    else {
      const r = $('Zugangsdaten setzen').first().json || {};
      const st = Number(r.statusCode) || 0;
      if (st !== 200) { test_ok = false; meldung = 'Der Schlüssel war gültig, konnte aber in n8n nicht gespeichert werden (' + (st ? 'Status ' + st : 'keine Antwort') + ').'; }
      else meldung = '';
    }
  }
}
let quelle = String(V.quelle || '');
if (!quelle) { try { quelle = String(JSON.parse(F.daten).quelle || ''); } catch (e) { quelle = ''; } }
return [{ json: { token: F.token, daten: JSON.stringify({ test_ok, meldung: meldung.slice(0, 300), quelle }) } }];

// Zurück auf die Seite Einstellungen > KI (Stefan 18.10.2026); Sitzung wie bei ALLY 8 behandeln (wie ALLY 14)
const SEITE = '/webhook/web';
const F = $('Formular prüfen').first().json;
// Stelle auf der Seite: Position, offene Bereiche und Formular aus der Adresse des Formulars wieder anhängen, damit die Seite nicht nach oben springt (wie ALLY 11)
const ZQ = $('Formular').first().json.query || {};
const stelle = ziel => { const y = String(ZQ.zy || ''), o = String(ZQ.zo || ''), f = String(ZQ.zf || ''), t = String(ZQ.zt || '');
  if (!/^[0-9]{1,6}$/.test(y)) return ziel;
  const z = ziel.split('#')[0], s = 'zy=' + y + (/^[0-9]{1,3}(\.[0-9]{1,3}){0,39}$/.test(o) ? '&zo=' + o : '') + (/^[A-Za-z0-9_-]{0,60}~[0-9]{1,3}$/.test(f) ? '&zf=' + f + (/^-?[0-9]{1,5}$/.test(t) ? '&zt=' + t : '') : '');
  return z + (z.includes('?') ? '&' : '?') + s; };
const r = ($('Abschließen').isExecuted ? $('Abschließen').first().json.r : $('Vorbereiten').first().json.v) || {};
const keks = (wert, alter) => 'ally_sitzung=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=None';
let ziel, cookie = '';
if (F.herkunft !== 'ok' || r.ungueltig) ziel = SEITE + '?m=ungueltig';
else if (r.angemeldet === false) { ziel = SEITE + '?m=abgelaufen'; cookie = keks('', 0); }
else { ziel = stelle(SEITE + '?ansicht=einstellungen&bereich=ki'); if (F.token) cookie = keks(F.token, 2592000); }
return [{ json: { ziel, set_cookie: cookie } }];
